export const meta = {
  name: 'whats-next-survey',
  description: 'Survey the apivo-news backlog, code state and blockers to decide what to build next',
  phases: [
    { title: 'Survey', detail: 'eight read-only investigators across branch, specs, backlog, blockers, UI, bugs, hygiene' },
    { title: 'Critique', detail: 'a completeness critic looks for what the survey missed' },
  ],
}

const FINDING_SCHEMA = {
  type: 'object',
  properties: {
    area: { type: 'string', description: 'Short name for the dimension surveyed' },
    summary: { type: 'string', description: '2-5 sentence grounded summary of the true state, citing file:line or issue numbers' },
    candidates: {
      type: 'array',
      description: 'Concrete pieces of work that could be started next in this area',
      items: {
        type: 'object',
        properties: {
          title: { type: 'string' },
          issues: { type: 'string', description: 'GitHub issue numbers involved, comma separated, or "none"' },
          evidence: { type: 'string', description: 'file:line or issue/PR references proving this is genuinely unbuilt or broken' },
          size: { type: 'string', enum: ['tiny', 'small', 'medium', 'large'] },
          blocked_by: { type: 'string', description: 'What blocks it, or "nothing"' },
          value: { type: 'string', description: 'Why it matters now, in one sentence' },
        },
        required: ['title', 'issues', 'evidence', 'size', 'blocked_by', 'value'],
      },
    },
    stale_issues: {
      type: 'array',
      description: 'Open issues whose work already appears done in the code — candidates to close',
      items: { type: 'string' },
    },
    surprises: { type: 'array', items: { type: 'string' }, description: 'Anything unexpected or contradictory found' },
  },
  required: ['area', 'summary', 'candidates', 'stale_issues', 'surprises'],
}

const PREAMBLE = `You are surveying the repository at C:/Users/madym/repos/apivo-news (Go backend + Astro frontend, "apivo-news" / cashback product).

RULES:
- READ ONLY. Do not edit, write, commit, or push anything. Do not create or close issues.
- The local branch is xcoder/member-signin and is BEHIND origin/main. Read files from origin/main with "git show origin/main:<path>" when the working tree may be stale, and use "git ls-tree -r --name-only origin/main -- <dir>" to list.
- This repo is indexed by graft. Prefer "graft ask", "graft grep", "graft skeleton", "graft callers" over blind grepping. Use "gh issue view N" / "gh pr view N" for issue and PR detail.
- VERIFY CLAIMS AGAINST CODE, not against issue titles. Many open issues may already be implemented; many specs describe work that does not exist. Say which is which and cite file:line.
- Be specific and terse. Your return value is data for a planning decision, not prose for a human.

`

phase('Survey')

const DIMENSIONS = [
  {
    key: 'branch',
    prompt: `${PREAMBLE}DIMENSION: the in-flight branch and PR.
Open PR #531 ("A member sign-in page that states what is owed rather than mocking it up") is on branch xcoder/member-signin, all CI checks green, unmerged. It carries commits 152e8fa and a6f5ba5 for issue #529.
Determine: (a) does the branch fully satisfy issue #529 as written (read "gh issue view 529")? (b) what exactly did it build - read the diff "git diff origin/main...HEAD --stat" then read the added files; (c) is anything missing that a reviewer would demand: tests, i18n catalogue entries, a11y, FAQ/footer linkage, brand-literal lint compliance? (d) since every control is DISABLED, what is the natural follow-up issue that makes sign-in actually work, and does an issue already exist for it? (e) does the branch merge cleanly onto current origin/main?`,
  },
  {
    key: 'spec005',
    prompt: `${PREAMBLE}DIMENSION: spec 005, "Evidence a member can check" (triple-entry / provable evidence).
Read origin/main:specs/005-provable-evidence/spec.md and research.md in full.
Determine: (a) what it actually proposes to build, concretely; (b) it says Status "Draft - awaiting founder answers to Q14-Q16" - what exactly are Q14, Q15, Q16 and what does each gate? (c) it says it is queued behind the local end-to-end demo (PR #533, now merged) - so is that gate now cleared? (d) does it have plan.md / tasks.md / contracts/ yet, and are there GitHub issues for it? (e) what is the smallest genuinely buildable first slice that does NOT depend on the unanswered founder questions? Cite the spec's own section headings.`,
  },
  {
    key: 'claims003',
    prompt: `${PREAMBLE}DIMENSION: spec 003, cashback claims (the largest coherent unbuilt feature).
Roughly 45 open issues CB-T148 through CB-T192 (issues #448-#492) belong to it. Read origin/main:specs/003-cashback-claims/ (spec.md, plan.md, tasks.md, data-model.md, contracts/).
Determine: (a) how much of it exists in code today - does internal/cashback/claims/ exist at all? (b) the dependency-ordered first buildable chunk (constitution amendment #448, founder ratification #449, migrations #450-#453, ...); (c) issue #508 says "specs/003-cashback-claims claims migrations 0033-0035, which 004 reserved" - is that still true? What migration numbers are actually free? Check internal/platform/db/migrations/ on origin/main and list the highest number in use. (d) is #448 (constitution amendment) a hard prerequisite for any code? (e) realistically, what is the first PR someone should open for 003?`,
  },
  {
    key: 'backlog002',
    prompt: `${PREAMBLE}DIMENSION: spec 002, the cashback alpha backlog - which foundational pieces are genuinely still missing.
About 63 open issues carry label area:cashback. Suspiciously foundational ones are still open: #187 CB-T040 (mount the cashback route tree behind CASHBACK_ENABLED), #196 CB-T049 (the Network port), #191 CB-T044 (Postgres ledger), #177 CB-T030 (TS type generation for the cashback schema), #195 CB-T048, #203 CB-T056, #206 CB-T059.
For EACH of those, check whether the code already exists (graft grep / graft ask; look under internal/cashback/, cmd/apivo/) and report done-vs-open. Then list which spec-002 issues are genuinely unbuilt and which of those unlock the most downstream work. Read origin/main:specs/002-apivo-cashback-alpha/tasks.md if present to get the intended order.`,
  },
  {
    key: 'blockers',
    prompt: `${PREAMBLE}DIMENSION: founder-blocked work.
Nine open issues carry label blocked:founders: #524, #446, #445, #444, #443, #442, #282, #95, #37.
PR #536 just merged "Record the founder decisions on Q4-Q7" (commit 486e541, touching specs/002-apivo-cashback-alpha/spec.md). Read that commit's diff in full: "git show 486e541".
Determine: (a) exactly which questions Q4-Q7 answered and what each answer was; (b) which of the nine blocked issues those answers now UNBLOCK, wholly or partly - be precise, quote the decision text; (c) which questions remain genuinely open (Q1, Q3, Q8, Q9, Q14-Q16, and anything in #37) and what each one blocks; (d) for #524 specifically (Linkwise sub-id parameter), note that PR #535 landed an "attribution canary" - read "git show 57ee7e3 --stat" and "gh issue view 524" and say whether #524 is now mitigated or still hard-blocked. (e) Which single founder decision, if answered today, would unblock the most work?`,
  },
  {
    key: 'frontend',
    prompt: `${PREAMBLE}DIMENSION: the member-facing frontend surface, built vs missing.
List every page that exists under web/src/pages/ (use "git ls-tree -r --name-only origin/main -- web/src/pages/"). Recent merges added: the FAQ (#530), the section nav (#526), the operator entrance (#527), and in flight the sign-in (#531).
Determine: (a) the full inventory of existing member-facing routes and ops routes; (b) which product surfaces named by the specs and the open issues are still absent - catalogue listing (#253 CB-T106), merchant detail (#254 CB-T107), wallet (#229 CB-T082), withdraw (#243 CB-T096), claims form/record (#480/#481), ops queues (#482, #262, #267, #244); (c) how the existing pages get their data - is there a fixture-fallback client pattern (look at web/src/lib/) that a new page should follow? Cite the file. (d) which single missing screen would most increase what a viewer of the product can actually see and click, given the demo (PR #533) now exists; (e) the copy discipline: how do existing pages source their strings (web/src/lib/*/strings.ts? web/src/i18n/?) and what is the brand-literal lint rule a new page must satisfy?`,
  },
  {
    key: 'bugs',
    prompt: `${PREAMBLE}DIMENSION: open correctness bugs and internal contradictions - triage for realness and urgency.
Triage these open issues by reading each with "gh issue view N" AND verifying against the code: #513 (FR-091 and contracts/config.md disagree with the code about what an incomplete network stops), #508 (migration numbering conflict), #503 (the outbox is write-only: no event consumer is ever constructed by the binary), #409 (lock-ordering deadlock between public.account and cashback.payout), #414 (GET /catalogue documents a category filter, but categories do not exist), #117 and #116 and #132 (flaky/polluting tests), #129 (editorial outcome notices never announced after POST), #138 (chrome labels an editor 'reader'), #95 (GDPR erasure vs append-only consent guard).
For each: is it still real in today's code (cite file:line), how bad is it, and how big is the fix? Rank them. Call out any that are silent money-losing or data-integrity risks versus cosmetic ones.`,
  },
  {
    key: 'hygiene',
    prompt: `${PREAMBLE}DIMENSION: working-tree and repo hygiene.
"git status" on branch xcoder/member-signin shows modified: .claude/settings.json, .githooks/commit-msg, .githooks/pre-push, .gitignore; and untracked: .claude/helpers/, .claude/skills/graft/, .entire/, .githooks/commit-msg.pre-entire, .githooks/post-commit, .githooks/post-rewrite, .githooks/pre-push.pre-entire, .githooks/prepare-commit-msg, .ignore, .mcp.json, .wrangler/, docs/demo-recording-prompt.md.
Determine for each: what it is, whether it should be committed, gitignored, or deleted. Read the modified hook diffs ("git diff .githooks/ .gitignore .claude/settings.json") and say whether the modifications WEAKEN the enforcement that CLAUDE.md and .specify/memory/constitution.md require - specifically scripts/lint-refs.sh and scripts/lint-commit-authors.sh must still run on pre-push, and .claude/hooks/session-start.sh must still set the git identity. That is the highest-stakes question here: flag loudly if any guard was disabled or renamed away (note the ".pre-entire" backups suggest a tool rewrote them).
Also: does docs/demo-recording-prompt.md belong in the repo, and does .mcp.json contain anything secret? Do NOT print secret values - just say whether any exist.`,
  },
]

const survey = (await parallel(DIMENSIONS.map(d => () =>
  agent(d.prompt, { label: `survey:${d.key}`, phase: 'Survey', schema: FINDING_SCHEMA })
))).filter(Boolean)

phase('Critique')

const critic = await agent(
  `${PREAMBLE}You are a COMPLETENESS CRITIC. Eight investigators surveyed this repo to answer one question: "what should the founder work on next, now that PR #530 has merged?"

Here is everything they returned, as JSON:

${JSON.stringify(survey, null, 2)}

Your job is to find what they MISSED and what they got WRONG.
1. Verify the three highest-stakes factual claims above against the actual code/issues yourself. Name any that are wrong.
2. Name work that is obviously next but that NO investigator mentioned. Check at least: is PR #531 mergeable right now and is that itself the answer; the docs/ tree (RUNBOOK, ENVIRONMENTS, SHOWCASE, adr/, master-prompts/) for promised-but-missing documentation; the CI workflows in .github/workflows/ for anything red or missing; test coverage gates the specs demand (#278, #491); and whether any merged spec has no issues filed against it at all.
3. State which ONE candidate across the whole survey you would rank first and why, and which is the most over-rated.
Be adversarial. Default to "the survey is incomplete" and prove it.`,
  { label: 'critic:completeness', phase: 'Critique', schema: {
    type: 'object',
    properties: {
      wrong_claims: { type: 'array', items: { type: 'string' } },
      missed_work: { type: 'array', items: { type: 'string' } },
      top_pick: { type: 'string' },
      top_pick_reason: { type: 'string' },
      overrated: { type: 'string' },
    },
    required: ['wrong_claims', 'missed_work', 'top_pick', 'top_pick_reason', 'overrated'],
  } }
)

return { survey, critic }

